const pad=p=>{ if(!p||p.mc||typeof p.v!=="number"||p.parts) return p; const a=String(p.a), seen=new Set([a]), w=[];
  p.w.forEach(x=>{ x=String(x); if(!seen.has(x)&&x!=="NaN"){ seen.add(x); w.push(x); } });
  let c; if(/\//.test(a)){ const m=a.replace("−","-").split("/"), n=+m[0], d=+m[1]; c=[F(-n,d),F(d,n||1),F(n+1,d),F(n,d+1)]; }
  else { const v=p.v, dec=(a.split(".")[1]||"").length, f=x=>N(+x.toFixed(dec)), st=Math.abs(v)>=20?10:Math.abs(v)>=5?2:1; c=[f(2*v),f(v+st),f(v-st),f(v+2*st),f(v/2)].filter(x=>v<=0||!/^−/.test(x)); }
  c.forEach(x=>{ if(w.length<3&&!seen.has(x)&&x!=="NaN"){ seen.add(x); w.push(x); } }); p.w=w; return p; };
const wrap=g=>()=>{ for(let i=0;i<40;i++){ const p=g(); if(p) return pad(p); } return pad(g()); };
